namespace OpenTPW;

/// <summary>Every unproven sound rule (docs/AUDIO.md "Approximation register"); logged once when the sound service starts.</summary>
public static class AudioApproximations
{
	public static readonly (string Id, string Rule)[] All =
	{
		("AUDIO-003", "the pitch is applied (a step drawn min + r % (max - min) per playback and played at ratio 1 or 2^(sign * (|step| + 1) / 96), tp.exe 0x6bc170 / 0x6d2820, confirmed by 141 playbacks of the original's video); a parameter-bound pitch slot is applied to every playback through its placeholder table (tp.exe 0x6bbf60 / 0x6bc040 / 0x6bc170); the fixed-pitch flag 0x10000 (0x6bc484) is unreachable (nothing sets it, the events' flags are 16-bit); the delay of every sample start is drawn after the volume and the pitch (min + r % (max - min), 0x6bc2d0, stored at +0x3c by 0x6bc4fa) and is a chain's wait between children, or for any other voice the time it keeps its place in the pool after its sample's nominal end plus 250 ms (0x6bc01b, 0x6bcb60, 0x6b62b0; events flagged 0x4 or 0x8 are exempt); reverb is AUDIO-039 (SndReverb.map is loaded at 0x6c5d20; tp.exe imports none of QMixer's reverb calls); chain delays are milliseconds (video, 2026-10-15); position is applied only by the positioned playback path"),
		("AUDIO-004", "0xBD plays instead of 0x1F when the receiver of the control message 0x100 has style bit 0x10 (tp.exe 0x4857cb): the global hook 0x485780 is called from 0x658d9f (0x658dd0) with the receiving window, and the receiver of a button-class release (0x668f9c, send 0x6691eb) is the pressed control's parent (this+0x60), not the control; 0x658683 sends nothing, and 0x65f5dc, 0x65f623 and 0x66fa2c are synchronous notifies whose receivers' classes are not decoded; the creation sites with the bit are read (the row templates 0x4938c0, 0x4944d0, 0x496cea/0x496cff, 0x4b4c70 and the table builder's type 3 sliders at 0x6604a1, 0x66051a, 0x6610b6, 0x661144, whose rows are styled 0 and so reach 0x1F when a child is pressed), but which window receives 0x100 for a press on a slider or a row child is not established, so every OpenTPW control plays 0x1F"),
		("AUDIO-018", "a positioned mono voice follows the software channel stage of QMixer.dll, which tp.exe selects for every voice (the request flag 1 is ORed in unconditionally at 0x6bc61b, so 0x6d23ab hands QSWaveMixConfigureChannel the mode 0x1000000, whose buffers have no DirectSound 3D object): the source's offset is rotated into the listener's basis (front and up from the camera matrix rows 0x7909b0 and 0x7909a0, right = up x front, 0x1800ce70, 0x1800cf10), the azimuth atan2(x, z) in degrees (0x1800cb10) becomes a DirectSound pan of 44.444 hundredths of a dB per degree mirrored behind the listener (0x18005730), the gain a volume of 2000 log10(gain) hundredths of a dB (0x1800ca40), and 0x18005830 sets both for a mono wave only (0x18005982 tests the format table 0x1803c6b4); the opposite channel is 10^(-|pan|/2000) of the level; the axis mapping of the camera rows into the listener (the swap flag of the tp.exe adapters 0x6d2aec and 0x6d2c68, byte +8 of the driver) and how QMixer places the flat voices that tp.exe positions at (0,1,0) (0x6bc51d, SetPosition 0x6d2640 against SetSourcePosition) are not read, so flat voices keep both channels at the voice's gain"),
		("AUDIO-039", "SETREVERB's preset is selected as the original selects it (the ridden ride's root script level, else 0; tp.exe 0x55A470 -> 0x51C8D0, sent only on a change) and its SndReverb.map record (0x6C5D20, 0x6C6000) is mixed by ReverbUnit, an OpenTPW Freeverb-style network on the positioned effects with the record's decay time, high-frequency ratio, diffusion, size, levels and delays; the original has no software reverb to port: it hands the record (13 dwords, EAX 2.0 listener order, 0x6C46B0) to the audio device or to the backend's vtable slot 0x50, and QMixer.dll's QSWaveMixSetReverb* forward to a COM object and hold no DSP, so the network, its constants, the size mapping and which voices it covers are OpenTPW's"),
		("AUDIO-038", "the voice pool of 12 (tp.exe 0x6b62b0) ranks the held chains (screams) with the running sentences, placed sounds and one-shots of the event system by priority and ground distance (0x6bb9f0), a voice entering only while its rank exceeds the pool's lowest (0x6b6bc0) and among equal ranks the newer voice keeping its slot (0x6b6a80 links a new voice at the head of the voice list); a voice out of range without the any-distance flag (event flag 0x200, voice flag 8 at 0x6bca44) has its sample stopped by mixer message 3 (0x6bca70 -> 0x6b8d60 -> 0x6bb7c0) and its handle at +0x24 left in place, and is not ticked: OpenTPW stops one-shots and sentence segments, and a chain starts no new child, but a chain's children already playing play out and looping voices are not stopped (nothing read restarts a stopped loop); how a stopped sentence resumes is not read and voices the mixer plays outside the event system, including the children a chain makes, do not compete"),
		("AUDIO-040", "FADEOBJ on a script's sound records stops the sound exactly as KILLOBJ does (tp.exe 0x5523D0 -> 0x51C300 -> 0x6B8930 takes the stop call 0x6B89B0 unless bit 0x400 of the sound library's settings word is set), which is the original's behaviour at SoundQuality 0: the bit is `SoundQuality > [0x785920]` (0x51B920, sent from the options apply 0x4237F0 and the sound start 0x54DE0E) and the threshold and the default [0x78591C] are never written (BSS), so the bit is clear in a fresh install; with SoundQuality above 0 the call is the voice's vf+0x30 (0x6B7130), which only stores 0x3C as the fixed volume (placeholder +0x44) and sets the flag 0x400, the manager tick (0x6B62B0) re-applies 60 % to the playing sample (vf+0x2C, 0x6BCB80, while the manager byte +0x50 is set) and the voice, whose record is freed, plays on dimmed instead of ending; OpenTPW has no SoundQuality option"),
		("AUDIO-900", "the rain and snow field follows the original CRain with its absolute parallax (wrapped fall - factor x the camera position, on the original's 1/16384 grid, 0x57efd0, 0x580013-0x5800b7) and its render states (0x567620: rain and bolts 0x200D52 source alpha over one without depth writes, snow 0x556 alpha blend with depth writes, all alpha-tested at 0x10 of 255), but the factor 0.3 (0x580003-0x58000b) applies in OpenTPW's free-walk and ride cameras, the mapping the listener uses for the same camera-state bits 0x16 of 0x790ab0 (EXT:listener-eye-mode); what those bits select in the original is not read (0x42AB20 toggles bits 2 and 4 from input events 2 and 4, the scene render 0x576a00 turns any of them into render flag 0x100 of 0x8bd508 and with it the alternative scene path 0x56ea90, and no instruction sets 0x10 alone), so which original views take 0.3 is not known"),
		("AUDIO-901", "snow draws the jitter version (((rand & 31) - 16) / 2048 a frame on every axis), as the PC always does (the swirl's flag 0x8bcbc8 bit 0x100 is never set), each flake one triangle over its atlas quadrant (apex at the top middle, base at the lower corners; 0x57f490) with its depth moved by 0.1501 (the depth-buffer value is [EXT:snow-depth-value]); the flake's base half-width is h x 0x8bcbcc (the display's height / width) in the original and w = h here, the same only if OpenTPW's aspect-correct projection stands for that factor, and the space of the vertex's z + 0.1 and fourth word z + 0.1501 (camera or clip) is not read"),
		("AUDIO-902", "the bolt follows tp.exe: the sky and ground points (0x512C50: the ground point is the strike's own x and z at y = 0, the sky point 300 up and offset by up to 50), the midpoint displacement and branch heading on the CRain stream (0x57E4B0, 0x57E810: stop threshold tested on each half, branch odds 9/512, depth limit 4), the colour pulse (0x57EE30) and the lifetime; but the ribbon is a camera-facing world quad of half-width 1.3 / (depth + 1) original units per segment without joins, where the emitter 0x57DD10 builds it in clip xy with joins between consecutive segments of one depth and a width of 1.3 / (depth + 1) clip units: it keeps per depth the previous projected point, direction (scaled to that width) and corner pair, a joint's corners are the point plus and minus the perpendicular of the normalised sum of the two directions around it (the point's clip z and w kept), the start corners use the first direction and the end corners the last, and a quad is emitted when the point after next arrives (the closing call 0x57EC50 -> 0x57DD10(0, end) emits the last quad from the corners two points back), the projection FUN_00578d20 and the quad's winding being the parts not yet matched"),
		("AUDIO-904", "the rain field lives within +-0.8 engine units of the eye, so the scene camera's 0.1 near plane (0.5 original units; kept for the weather as [EXT:weather-near-plane]) clips the nearest drops where the original's near plane is 0.1 original units (0x54e86f and the camera init 0x42a990 -> 0x578be0: near 0.1, far 1000, field of view 90) and its polygon clipper (clip codes 0x561bc0, clipping 0x562a70 in 0x565bb0) cuts the streaks there, drawing only drops in front of the eye (0x57f1f0)"),
	};

	private static bool logged;

	public static void LogOnce()
	{
		if ( logged )
			return;
		logged = true;
		foreach ( var (id, rule) in All )
			Log.Trace( $"[APPROX:{id}] {rule}" );
	}
}
